"use strict";
// Optional integration fixture; all generated bytes live in the host's isolated workspace.
const path = require("node:path");
const { promisify } = require("node:util");
const execFile = promisify(require("node:child_process").execFile);
module.exports = async function seed({ call, workspace, fixture }) {
  const { id, episodeId, shotId, assets } = fixture;
  await execFile("ffmpeg", ["-hide_banner","-loglevel","error","-f","lavfi","-i","color=c=gray:s=96x64:r=12:d=2","-an","-c:v","libvpx","-deadline","realtime","-y",path.join(workspace,"bone-media/clip.webm")]);
  await execFile("ffmpeg", ["-hide_banner","-loglevel","error","-f","lavfi","-i","anullsrc=r=8000:cl=mono","-t","2","-c:a","pcm_s16le","-y",path.join(workspace,"bone-media/sound.wav")]);
  await call("update_shot", { id, shotId,
    videoPlan:{mode:"first-last-frame",firstFrameAssetId:assets[0].id,lastFrameAssetId:assets[1].id,transitionIn:"hard-cut",rationale:"Keep both frame roles"},
    continuityPlan:{entryState:"Enter the alley",exitState:"Stop at the door",rationale:"Same direction",audioTransition:"carry-over",anchors:[]} });
  const read = () => call("get_production", { id });
  const revision = (await read()).shotStates[shotId].revision;
  const video = await call("register_media", { id, path:"bone-media/clip.webm",kind:"video",title:"Adopted clip",shotId,expectedShotRevision:revision });
  const audio = await call("register_media", { id, path:"bone-media/sound.wav",kind:"audio",title:"Independent sound",shotId,expectedShotRevision:revision });
  await call("adopt_media", { id,shotId,mediaId:video.mediaId,expectedShotRevision:revision });
  await call("adopt_media", { id,shotId,mediaId:audio.mediaId,expectedShotRevision:revision });
  const beatId = (await read()).production.episodes[0].script.beats[0].id;
  const second = await call("add_shots", { id,episodeId,shots:[{title:"Second shot",scene:"Continue outside",beatId,duration:2}] });
  const empty = await call("write_script", { id,title:"Other episode",prose:"A different episode without shots." });
  const guarded = async (name,args) => call(name,{id,expectedProductionRevision:(await read()).production.revision,...args});
  for (const media of [video,audio]) await guarded("record_media_inspection", { mediaId:media.mediaId,sha256:media.sha256,durationSeconds:2,method:"Deterministic ffmpeg fixture",findings:"Two-second local test source",usableRanges:[{inSeconds:0,outSeconds:2,note:"Synthetic test segment"}] });
  const clips = [["clip-one",0,0.5],["clip-two",0.5,1]].map(([clipId,inSeconds,outSeconds]) => ({clipId,shotId,mediaId:video.mediaId,inSeconds,outSeconds,speed:1,includeSourceAudio:false,note:"Keep fixture segment"}));
  await guarded("save_edit_plan", {episodeId,expectedEditRevision:0,clips,audioTracks:[{trackId:"music-track",mediaId:audio.mediaId,role:"music",startSeconds:0,inSeconds:0,outSeconds:1,gain:0.5,note:"Fixture audio"}],cutNotes:[{fromClipId:"clip-one",toClipId:"clip-two",visual:"Match fixture cut",audio:"Carry fixture audio"}],notes:"Saved episode fixture"});
  for (const [scope,findings] of [[{kind:"shot",shotId},"Shot review fixture"],[{kind:"episode",episodeId},"Episode review fixture"]]) {
    await guarded("record_review", {scope,category:"text",verdict:"not-verified",evidence:[],findings,nextAction:"Inspect before approval"});
  }
  return {video,audio,secondShotId:second.shots[0].id,emptyEpisodeId:empty.episodeId};
};
